import React, { useState, useEffect } from "react"
import { graphql } from "gatsby"
import _ from "lodash"

import Layout from "components/Layout"
import SEO from "components/SEO"
import PostList from "components/PostList"
import SeriesList from "components/SeriesList"
import VerticalSpace from "components/VerticalSpace"

const SeriesPage = ({ data }) => {
  const posts = data.allMarkdownRemark.nodes
  const tags = data.allMarkdownRemark.group
  
  // 시리즈가 있는 포스트들만 필터링
  const seriesPosts = posts.filter(post => post.frontmatter.series)
  
  // 시리즈별로 그룹화
  const seriesGroups = _.groupBy(seriesPosts, 'frontmatter.series')
  
  const [filteredPosts, setFilteredPosts] = useState(posts)
  const [selectedSeries, setSelectedSeries] = useState(null)

  const handleClickSeries = series => {
    if (selectedSeries === series) {
      setSelectedSeries(null)
      setFilteredPosts(posts)
    } else {
      setSelectedSeries(series)
      setFilteredPosts(seriesGroups[series] || [])
    }
  }

  useEffect(() => {
    setFilteredPosts(posts)
  }, [posts])

  return (
    <Layout>
      <SEO title="Series" />
      <VerticalSpace size={48} />
      <SeriesList
        seriesGroups={seriesGroups}
        selectedSeries={selectedSeries}
        onClick={handleClickSeries}
      />
      <PostList postList={filteredPosts} />
    </Layout>
  )
}

export default SeriesPage

export const pageQuery = graphql`
  query {
    site {
      siteMetadata {
        title
      }
    }
    allMarkdownRemark(
      sort: { frontmatter: { date: DESC } }
      filter: { fileAbsolutePath: { regex: "/contents/posts/" } }
    ) {
      group(field: { frontmatter: { tags: SELECT } }) {
        fieldValue
        totalCount
      }
      nodes {
        excerpt(pruneLength: 200, truncate: true)
        html
        fields {
          slug
        }
        frontmatter {
          date(formatString: "YYYY년 M월 D일")
          update(formatString: "YYYY년 M월 D일")
          title
          tags
          series
        }
      }
    }
  }
`
