import React from "react"
import styled from "styled-components"
import _ from "lodash"

const SeriesListWrapper = styled.div`
  margin-bottom: 40px;
  @media (max-width: 768px) {
    padding: 0 16px;
  }
`

const SeriesGrid = styled.div`
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 20px;
  margin-bottom: 32px;

  @media (max-width: 768px) {
    grid-template-columns: 1fr;
    gap: 16px;
  }
`

const SeriesCard = styled.div`
  background: ${props => props.theme?.name === 'dark' ? '#1a1a1a' : '#ffffff'};
  border: 1px solid ${props => props.selected 
    ? '#2563eb' 
    : props.theme?.name === 'dark' ? '#2a2a2a' : '#e5e7eb'
  };
  border-radius: 12px;
  padding: 20px;
  cursor: pointer;
  transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
  position: relative;
  overflow: hidden;

  &::before {
    content: '';
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 3px;
    background: linear-gradient(135deg, #2563eb 0%, #7c3aed 100%);
    opacity: ${props => props.selected ? 1 : 0};
    transition: opacity 0.3s ease;
  }

  &:hover {
    transform: translateY(-2px);
    box-shadow: 0 8px 24px ${props => props.theme?.name === 'dark' ? 'rgba(59, 130, 246, 0.15)' : 'rgba(37, 99, 235, 0.1)'};
    border-color: #2563eb;
  }

  &:hover::before {
    opacity: 1;
  }
`

const SeriesTitle = styled.h3`
  font-size: 18px;
  font-weight: 700;
  color: ${props => props.selected
    ? '#2563eb'
    : props.theme?.name === 'dark' ? '#ffffff' : '#0a0a0a'
  };
  margin-bottom: 8px;
  line-height: 1.3;
`

const SeriesInfo = styled.div`
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 14px;
  color: ${props => props.theme?.name === 'dark' ? '#9ca3af' : '#6b7280'};
`

const PostCount = styled.span`
  font-weight: 600;
  color: ${props => props.theme?.name === 'dark' ? '#3b82f6' : '#2563eb'};
`

const Title = styled.h2`
  font-size: 24px;
  font-weight: 700;
  color: ${props => props.theme?.name === 'dark' ? '#ffffff' : '#0a0a0a'};
  margin-bottom: 24px;
  text-align: center;
`

const AllSeriesButton = styled.button`
  display: block;
  width: 100%;
  max-width: 200px;
  margin: 0 auto 24px;
  padding: 12px 24px;
  background: ${props => props.selected 
    ? 'linear-gradient(135deg, #2563eb 0%, #7c3aed 100%)' 
    : props.theme?.name === 'dark' ? '#1a1a1a' : '#ffffff'
  };
  color: ${props => props.selected 
    ? '#ffffff' 
    : props.theme?.name === 'dark' ? '#d1d5db' : '#374151'
  };
  border: 1px solid ${props => props.selected 
    ? '#2563eb' 
    : props.theme?.name === 'dark' ? '#2a2a2a' : '#e5e7eb'
  };
  border-radius: 8px;
  font-size: 16px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);

  &:hover {
    background: ${props => props.selected 
      ? 'linear-gradient(135deg, #1d4ed8 0%, #6b21a8 100%)' 
      : 'linear-gradient(135deg, #2563eb 0%, #7c3aed 100%)'
    };
    color: #ffffff;
    border-color: #2563eb;
    transform: translateY(-1px);
    box-shadow: 0 4px 12px rgba(37, 99, 235, 0.3);
  }
`

const SeriesList = ({ seriesGroups, selectedSeries, onClick }) => {
  const seriesNames = Object.keys(seriesGroups || {})
  
  if (seriesNames.length === 0) {
    return (
      <SeriesListWrapper>
        <Title>시리즈가 없습니다</Title>
      </SeriesListWrapper>
    )
  }

  return (
    <SeriesListWrapper>
      <Title>{seriesNames.length}개의 시리즈가 있습니다</Title>
      
      <AllSeriesButton
        selected={!selectedSeries}
        onClick={() => onClick(null)}
      >
        모든 포스트 보기
      </AllSeriesButton>
      
      <SeriesGrid>
        {seriesNames.map(seriesName => {
          const seriesPosts = seriesGroups[seriesName] || []
          const latestPost = seriesPosts[0] // 이미 날짜순으로 정렬되어 있음
          
          return (
            <SeriesCard
              key={seriesName}
              selected={selectedSeries === seriesName}
              onClick={() => onClick(seriesName)}
            >
              <SeriesTitle selected={selectedSeries === seriesName}>
                {seriesName}
              </SeriesTitle>
              <SeriesInfo>
                <PostCount>{seriesPosts.length}</PostCount>
                <span>개의 포스트</span>
                {latestPost && (
                  <>
                    <span>·</span>
                    <span>{latestPost.frontmatter.date}에 마지막 업데이트</span>
                  </>
                )}
              </SeriesInfo>
            </SeriesCard>
          )
        })}
      </SeriesGrid>
    </SeriesListWrapper>
  )
}

export default SeriesList
